import ULThemeLogo from "@/components/ULThemeLogo";
import ULThemeSubtitle from "@/components/ULThemeSubtitle";
import ULThemeTitle from "@/components/ULThemeTitle";

import { useMfaPushChallengeManager } from "../hooks/useMfaPushChallengeManager";

function Header() {
  const { texts, locales } = useMfaPushChallengeManager();

  // Use Locales as fallback to SDK texts
  const titleText = texts?.title || locales.header.title;
  const descriptionText = locales.header.description;
  const logoAltText = texts?.logoAltText || locales.header.logoAltText;

// Función auxiliar que puedes poner fuera o dentro del componente
const renderWithBold = (text: string) => {
  // Dividimos el texto usando una expresión regular que busca "**texto**"
  const parts = text.split(/(\*\*.*?\*\*)/g);
  
  return parts.map((part, index) => {
    if (part.startsWith('**') && part.endsWith('**')) {
      // Quitamos los asteriscos y agregamos Tailwind
      return <span key={index} className="font-bold">{part.slice(2, -2)}</span>;
    }
    return part; // Retornamos el texto normal
  });
};


  return (
    <>
      <ULThemeLogo altText={logoAltText}></ULThemeLogo>
      <ULThemeTitle>{titleText}</ULThemeTitle>
      <ULThemeSubtitle className="mb-6 whitespace-pre-line">
        {renderWithBold(descriptionText)}
      </ULThemeSubtitle>
    </>
  );
}

export default Header;
