import CoppelPageLayout from "@/components/CoppelPageLayout";
import { ULThemeButton } from "@/components/ULThemeButton";
import ULThemeCard from "@/components/ULThemeCard";
import { applyAuth0Theme } from "@/utils/theme";
import { pushPageView, pushPhoneIdentifierReenviar } from "@/utils/helpers/dataLayerUtils";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { useEffect } from "react";

import Footer from "./components/Footer";
import Header from "./components/Header";
import PhoneIdentifierChallengeForm from "./components/PhoneIdentifierForm";
import { usePhoneIdentifierChallengeManager } from "./hooks/usePhoneIdentifierChallengeManager";

function PhoneIdentifierChallengeScreen() {
  // Extracting attributes from hook made out of PhoneIdentifierChallenge instance of Auth0 React ACUL SDK
  const {
    phoneIdentifierChallenge,
    texts,
    locales,
    handleResendCode,
    useResend,
  } = usePhoneIdentifierChallengeManager();

  const { disabled } = useResend({
    timeoutSeconds: 10,
  });

  const resendText = texts?.resendText || locales.footer.resendCodeText;
  const resendLinkText =
    texts?.resendActionText || locales.footer.resendButtonText;
  const resendLimitReachedText =
    texts?.resendLimitReachedText || locales.footer.limitReachedText;

  useEffect(() => {
    const canal = getCanalByClientId();
    pushPageView(
      "/recuperacion-contrasena/revisa-tu-celular",
      "Recuperación de contraseña - Revisa tu celular",
      canal
    );
  }, [phoneIdentifierChallenge.client.id]);

  const handleResendClick = async () => {
    const canal = getCanalByClientId();
    pushPhoneIdentifierReenviar("/recuperacion-contrasena/revisa-tu-celular", canal);
    await handleResendCode();
  };

  applyAuth0Theme(phoneIdentifierChallenge);
  document.title = texts?.pageTitle || locales.pageTitle;

  return (
    <CoppelPageLayout
      className="theme-universal"
      pageTitle={texts?.pageTitle || locales.pageTitle}
    >
      <div className="w-full max-w-[400px] pt-20">
        <ULThemeCard className="w-full gap-0">
          <Header />
          <div className="text-center mb-6">
            {/* Resend code section */}
            <div>
              {!disabled ? (
                <>
                  <span className="text-(length:--ul-theme-font-body-text-size) font-body">
                    {resendText}{" "}
                  </span>
                  <ULThemeButton
                    onClick={handleResendClick}
                    variant="link"
                    size="link"
                  >
                    {resendLinkText}
                  </ULThemeButton>
                </>
              ) : (
                <span className="text-(length:--ul-theme-font-body-text-size) font-body">
                  {resendLimitReachedText}
                </span>
              )}
            </div>
          </div>
          <PhoneIdentifierChallengeForm />
          <Footer />
        </ULThemeCard>
      </div>
    </CoppelPageLayout>
  );
}

export default PhoneIdentifierChallengeScreen;
