import ULThemeCard from "@/components/ULThemeCard";
import CoppelPageLayout from "@/components/CoppelPageLayout";
import { useEffect } from "react";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";
import { pushPageView } from "@/utils/helpers/dataLayerUtils";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";

import Header from "./components/Header";
import MfaPushChallengeForm from "./components/MfaPushChallengeForm";
import { useMfaPushChallengeManager } from "./hooks/useMfaPushChallengeManager";

function MfaPushChallengeScreen() {
  // Extracting attributes from hook made out of MfaPushChallenge instance of Auth0 React ACUL SDK
  const { texts, locales, mfaPushChallengePush } = useMfaPushChallengeManager();

  applyAuth0Theme(mfaPushChallengePush);
  document.title = texts?.pageTitle || locales.page.title;

  useEffect(() => {
    const canal = getCanalByClientId();
    pushPageView(
      "/protege-tu-cuenta/auth0-guardian",
      "Protege tu cuenta - Guardian",
      canal
    );
  }, []);

  return (
    <CoppelPageLayout className="theme-universal" pageTitle={locales?.page?.title} mainAriaLabel={locales?.header?.ariaDescription}>
      <ULThemeCard className="w-full max-w-[400px] gap-0">
        <Header />
        <MfaPushChallengeForm />
      </ULThemeCard>
    </CoppelPageLayout>
  );
}

export default MfaPushChallengeScreen;
