import { Button, type ButtonProps } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { extractTokenValue } from "@/utils/helpers/tokenUtils";

export type ULThemeButtonProps = ButtonProps;

export function ULThemeButton({
  variant = "primary",
  size = "default",
  className,
  ...props
}: ULThemeButtonProps) {
  // Determine if the button is effectively disabled
  const isDisabled =
    props.disabled ||
    props["aria-disabled"] === true ||
    props["aria-disabled"] === "true";

  // Using extractTokenValue utility to extract the link style variant type from the CSS variable
  const linkStyleValue =
    extractTokenValue("--ul-theme-font-links-style") === "normal"
      ? "no-underline"
      : "underline";

  // Variant-specific theme overrides for colors and states
  const variantThemeOverrides = {
    primary: cn(
      "p-6 border-0",
      "rounded-full",
      "theme-universal:focus:outline-none theme-universal:focus:ring-4 theme-universal:focus:ring-base-focus/15",
      isDisabled
        ? "bg-[#bdbdbd] text-[#717171] opacity-100 cursor-not-allowed hover:bg-[#bdbdbd]"
        : cn(
            "cursor-pointer",
            "theme-universal:bg-primary-button",
            "theme-universal:text-(--ul-theme-color-primary-button-label)",
            "theme-universal:hover:shadow-[var(--button-hover-shadow)]"
          )
    ),
    secondary: cn(
      "p-6",
      "theme-universal:border-1 theme-universal:focus:ring-4 theme-universal:focus:ring-base-focus/15",
      isDisabled
        ? "opacity-50 cursor-not-allowed"
        : cn(
            "cursor-pointer",
            "theme-universal:text-link-focus",
            "theme-universal:border-(--ul-theme-color-primary-button)",
            "theme-universal:hover:shadow-[var(--button-hover-shadow)]"
          )
    ),
    destructive: "",
    outline: cn(
      "p-6",
      "theme-universal:border-1 theme-universal:focus:ring-4 theme-universal:focus:ring-base-focus/15",
      isDisabled
        ? "opacity-50 cursor-not-allowed"
        : cn(
            "cursor-pointer",
            "theme-universal:text-(--ul-theme-color-secondary-button-label)",
            "theme-universal:border-(--ul-theme-color-secondary-button-border)",
            "theme-universal:hover:shadow-[var(--button-hover-shadow)]"
          )
    ),
    ghost: "",
    link: isDisabled
      ? "opacity-50 cursor-not-allowed text-link-focus focus:rounded-(--ul-theme-border-links-border-radius)"
      : `text-link-focus hover:no-underline cursor-pointer focus:rounded-(--ul-theme-border-links-border-radius) hover:text-link-focus/80 theme-universal:focus:outline-none theme-universal:focus:ring-4 theme-universal:focus:ring-base-focus/15 theme-universal:focus:bg-base-focus/15 ${linkStyleValue}`,
  };

  // Size-specific theme overrides for border radius and typography
  const sizeThemeOverrides = {
    default: cn(
      "theme-universal:rounded-full",
      "theme-universal:font-button", //font-weight
      "theme-universal:text-(length:--ul-theme-font-buttons-text-size)" //font-size
    ),
    xs: cn(
      "theme-universal:rounded-button",
      "theme-universal:font-button",
      "theme-universal:text-(length:--ul-theme-font-buttons-text-size)"
    ),
    sm: cn(
      "theme-universal:rounded-button",
      "theme-universal:font-button",
      "theme-universal:text-(length:--ul-theme-font-buttons-text-size)"
    ),
    lg: cn(
      "theme-universal:rounded-button",
      "theme-universal:font-button",
      "theme-universal:text-(length:--ul-theme-font-buttons-text-size)"
    ),
    icon: cn("theme-universal:rounded-button"),
    link: cn(
      "theme-universal:text-(length:--ul-theme-font-links-size)",
      "theme-universal:font-(weight:--ul-theme-font-links-weight)"
    ),
  };

  // Combine all theme classes with proper type safety
  const themeClasses = cn(
    variant && variantThemeOverrides[variant],
    size && sizeThemeOverrides[size]
  );

  const { onClick, ...restProps } = props;

  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isDisabled) {
      e.preventDefault();
      return;
    }
    if (onClick) {
      onClick(e);
    }
  };

  return (
    <Button
      variant={variant}
      size={size}
      className={cn(
        className, 
        themeClasses,
        isDisabled && "pointer-events-none" // Extra safety to avoid focus outline if not wanted or hover effects from base component
      )}
      onClick={handleClick}
      // Ensure aria-disabled is properly populated down to the button
      aria-disabled={isDisabled ? "true" : undefined}
      {...restProps}
    />
  );
}
