import ULThemeLogo from "@/components/ULThemeLogo";
import ULThemeSubtitle from "@/components/ULThemeSubtitle";
import ULThemeTitle from "@/components/ULThemeTitle";

import { usePhoneIdentifierChallengeManager } from "../hooks/usePhoneIdentifierChallengeManager";

function Header() {
  const { texts, data, locales } = usePhoneIdentifierChallengeManager();

  // Handle text fallbacks in component
  const logoAltText = texts?.logoAltText || locales.header.logoAltText;
  const phoneNumber = data?.phone || locales.header.phoneNumber;
  return (
    <>
      <ULThemeLogo altText={logoAltText}></ULThemeLogo>
      <div className="flex justify-center w-full mb-6">
        <svg xmlns="http://www.w3.org/2000/svg" width="39" height="67" viewBox="0 0 39 67" fill="none">
          <path d="M19.1667 60.5002C22.5 60.5002 25.1667 57.8335 25.1667 54.5002C25.1667 51.1668 22.5 48.5002 19.1667 48.5002C15.8334 48.5002 13.1667 51.1668 13.1667 54.5002C13.1667 57.8335 15.8334 60.5002 19.1667 60.5002Z" fill="#F0D224"/>
          <path d="M33.6667 3.33333C34.3333 3.33333 35 4 35 4.66667V62C35 62.6667 34.3333 63.3333 33.6667 63.3333H4.66667C4 63.3333 3.33333 62.6667 3.33333 62V4.66667C3.33333 4 4 3.33333 4.66667 3.33333H33.6667ZM33.6667 0H4.66667C2.16667 0 0 2.16667 0 4.66667V62C0 64.5 2.16667 66.6667 4.66667 66.6667H33.6667C36.1667 66.6667 38.3333 64.5 38.3333 62V4.66667C38.3333 2.16667 36.3333 0 33.6667 0Z" fill="#081754"/>
          <path d="M26.3326 7.83325C27.2531 7.83325 27.9993 8.57944 27.9993 9.49992C27.9993 10.4204 27.2531 11.1666 26.3326 11.1666H11.9999C11.0794 11.1666 10.3333 10.4204 10.3333 9.49992C10.3333 8.57944 11.0794 7.83325 11.9999 7.83325H26.3326Z" fill="#081754"/>
        </svg>
      </div>
      <ULThemeTitle className="mb-6 text-(--coppel-color-text-dark) justify-text-header text-(length:--ul-theme-font-title-size) font-title">{texts?.title || locales.header.title}</ULThemeTitle>
      <ULThemeSubtitle className="text-(--coppel-color-text-dark) justify-text-header text-(length:--ul-theme-font-subtitle-size) font-subtitle mb-6">
        Te enviamos un mensaje al celular <strong>{phoneNumber}</strong>
      </ULThemeSubtitle>
    </>
  );
}

export default Header;
