import { useForm } from "react-hook-form";

import { useErrors } from "@auth0/auth0-acul-react/mfa-push-welcome";
import type { CustomOptions, ErrorItem } from "@auth0/auth0-acul-react/types";

import { AppleIcon, GooglePlayIcon } from "@/assets/icons";
import { Form } from "@/components/ui/form";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import ULThemeLink from "@/components/ULThemeLink";
import { cn } from "@/lib/utils";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushMfaEnrollOption } from "@/utils/helpers/dataLayerUtils";

import { useMfaPushWelcomeManager } from "../hooks/useMfaPushWelcomeManager";

function MfaPushWelcomeForm() {
  const {
    links,
    texts,
    locales,
    handleMfaPushWelcomeEnroll,
    handlePickAuthenticator,
  } = useMfaPushWelcomeManager();

  // Initialize the form using react-hook-form
  const form = useForm<CustomOptions>({});

  


  // Use Locales as fallback to SDK texts
  const continueEnrollButtonText =
    texts?.buttonText || locales.form.continueEnrollButtonText;
  const androidButtonText =
    texts?.androidButtonText || locales.form.androidButtonText;
  const iosButtonText = texts?.iosButtonText || locales.form.iosButtonText;
  const pickAuthenticatorText =
    texts?.pickAuthenticatorText || locales.form.pickAuthenticatorText;
  const shouldShowTryAnotherMethod = true;

  const { errors, hasError, dismiss } = useErrors();

  // Get general errors (not field-specific)
  const generalErrors: ErrorItem[] = errors
    .byType("auth0")
    .filter((err) => !err.field);

  const onSubmit = async (formData?: CustomOptions) => {
    const canal = getCanalByClientId();
    pushMfaEnrollOption("Continuar", "/protege-tu-cuenta/auth0", canal);
    await handleMfaPushWelcomeEnroll(formData);
  };

  const socialIconButtonClassNames = cn(
    "flex items-center justify-center w-full h-[48px] py-4 px-4 gap-x-4",
    "bg-white border-gray-mid text-text-default cursor-pointer hover:no-underline",
    "theme-universal:font-button",
    "theme-universal:rounded-button",
    "theme-universal:border-(length:--ul-theme-border-button-border-weight)",
    "theme-universal:border-secondary-button-border",
    "theme-universal:text-secondary-button-label",
    "theme-universal:hover:shadow-(--button-hover-shadow)",
    "theme-universal:focus:outline-none theme-universal:focus:ring-4 theme-universal:focus:ring-base-focus/15 theme-universal:focus:bg-base-focus/15"
  );

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)}>
        {/* General error messages */}
        {generalErrors.length > 0 && (
          <div className="space-y-3 mb-4">
            {hasError &&
              generalErrors.map((error) => (
                <ULThemeAlert
                  key={error.id}
                  variant="destructive"
                  onDismiss={() => dismiss(error.id)}
                >
                  <ULThemeAlertTitle>
                    {error.message || locales.errors.errorOccurred}
                  </ULThemeAlertTitle>
                </ULThemeAlert>
              ))}
          </div>
        )}

        <div className="text-center">
          <div className="space-y-6">
            <ULThemeLink
              href={links?.ios}
              target="_blank"
              className={cn(socialIconButtonClassNames)}
              onClick={() => {
                const canal = getCanalByClientId();
                pushMfaEnrollOption(iosButtonText, "/protege-tu-cuenta/auth0", canal);
              }}
            >
              <span className="w-6 h-6 flex items-center justify-center [&_svg]:!size-6" aria-hidden="true">
                <AppleIcon />
              </span>
              <span className="wrap-break-word text-base whitespace-normal text-center text-(--coppel-color-text-dark)">
                {iosButtonText}
              </span>
            </ULThemeLink>
            <ULThemeLink
              href={links?.android}
              target="_blank"
              className={cn(socialIconButtonClassNames)}
              onClick={() => {
                const canal = getCanalByClientId();
                pushMfaEnrollOption(androidButtonText, "/protege-tu-cuenta/auth0", canal);
              }}
            >
              <span className="w-6 h-6 flex items-center justify-center [&_svg]:!size-6" aria-hidden="true">
                <GooglePlayIcon />
              </span>
              <span className="wrap-break-word text-base whitespace-normal text-center text-(--coppel-color-text-dark)">
                {androidButtonText}
              </span>
            </ULThemeLink>
          </div>
          {/* Continue Enroll Button */}
          <ULThemeButton
            type="submit"
            variant="primary"
            className="w-full mt-6"
          >
            {continueEnrollButtonText}
          </ULThemeButton>
        </div>
      </form>
      {/* Try another method link */}
      {shouldShowTryAnotherMethod && (
        <ULThemeButton
          onClick={() => {
            const canal = getCanalByClientId();
            pushMfaEnrollOption("Intentar con otro metodo", "/protege-tu-cuenta/auth0", canal);
            handlePickAuthenticator();
          }}
          variant="link"
          size="link"
          className="mt-6 text-center"
        >
          {pickAuthenticatorText}
        </ULThemeButton>
      )}
    </Form>
  );
}

export default MfaPushWelcomeForm;
