import { ULThemeButton } from "@/components/ULThemeButton";

function Footer() {
  return (
    <div className="text-center">
      {/* Go back button */}
      <div>
        <ULThemeButton
          onClick={() => (window.location.href = "/password-reset-request")}
          variant="link"
          size="link"
        >
          Regresar
        </ULThemeButton>
      </div>
    </div>
  );
}

export default Footer;
