import { useEffect } from "react";

import CoppelPageLayout from "@/components/CoppelPageLayout";
import ULThemeCard from "@/components/ULThemeCard";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushPageView } from "@/utils/helpers/dataLayerUtils";

import Header from "./components/Header";
import MfaOtpChallengeForm from "./components/MfaOtpChallengeForm";
import { useMfaOtpChallengeManager } from "./hooks/useMfaOtpChallengeManager";

const MfaOtpChallenge = () => {
  
  const isPushOtpChallenge = typeof window !== "undefined" && window.location.pathname.includes("mfa-push-otp-challenge");

  const { texts, locales, mfaOtpChallenge } = useMfaOtpChallengeManager();
  const pageTitle = texts?.title || locales.page.title;
  
// Condicional para la descripción:
  const ariaDescription = isPushOtpChallenge
    ? locales.header.descriptionPush
    : locales.header.description;

  applyAuth0Theme(mfaOtpChallenge);

  useEffect(() => {
    const canal = getCanalByClientId();

    const pagePath = isPushOtpChallenge
      ? "/protege-tu-cuenta/auth0-guardian-manual"
      : "/protege-tu-cuenta/google";

    const pageTitle = isPushOtpChallenge
      ? "Protege tu cuenta - Manual"
      : "Protege tu cuenta - Google";

    pushPageView(
      pagePath,
      pageTitle,
      canal
    );
  }, [isPushOtpChallenge]);

  return (
    <CoppelPageLayout className="theme-universal" pageTitle={pageTitle} mainAriaLabel={ariaDescription}>
      <ULThemeCard className="w-full max-w-[400px] gap-0">
        <Header isPushOtpChallenge={isPushOtpChallenge} />
        <MfaOtpChallengeForm />
      </ULThemeCard>
    </CoppelPageLayout>
  );
};

export default MfaOtpChallenge;
