import { useRef } from "react";
import { useForm } from "react-hook-form";

import { useErrors } from "@auth0/auth0-acul-react/mfa-otp-challenge";
import type { ErrorItem, WithRememberOptions } from "@auth0/auth0-acul-react/types";

import { Form, FormField, FormItem } from "@/components/ui/form";
import { pushClicHipervinculo, pushMfaOtpContinuar } from "@/utils/helpers/dataLayerUtils";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeCheckbox } from "@/components/ULThemeCheckbox";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";

import { useMfaOtpChallengeManager } from "../hooks/useMfaOtpChallengeManager";
import { ULThemeStaticLabelField } from "@/components/form/ULThemeStaticLabelField";

type MfaOtpFormData = { code: string } & WithRememberOptions;

function MfaOtpChallengeForm() {
  const {
    data,
    texts,
    locales,
    handleContinue,
    handleTryAnotherMethod,
  } = useMfaOtpChallengeManager();

  // Initialize the form using react-hook-form
  const form = useForm<MfaOtpFormData>({
    defaultValues: {
      code: "",
      rememberDevice: false,
    },
  });

  // Use Locales as fallback to SDK texts
  const rememberDeviceText = texts?.rememberMeText || locales.form.rememberDeviceText;
  const continueText = texts?.buttonText || locales.form.continueButton;
  const codeLabel = texts?.codeLabel || locales.form.codeLabel;
  const tryAnotherMethodText = texts?.pickAuthenticatorText || locales.form.tryAnotherMethodText;
  
  const { showRememberDevice } = data || {};
  const shouldShowTryAnotherMethod = false; // In OTP usually you want to allow changing method if they lost their device

  const { errors, hasError, dismiss } = useErrors();

  // Get errors
  const generalErrors = errors.byType("auth0").filter((err) => !err.field) as ErrorItem[];
  const codeErrors = errors.byField("code") as ErrorItem[];

  // Track the interaction type for analytics
  const interactionTypeRef = useRef<"Continuar" | "Enter">("Enter");

  const onSubmit = async (formData: MfaOtpFormData) => {
    // Push dataLayer event
    const canal = getCanalByClientId();
    pushMfaOtpContinuar(
      interactionTypeRef.current,
      "/protege-tu-cuenta/google",
      canal
    );

    // Reset interaction to default after submission
    interactionTypeRef.current = "Enter";

    // Basic validation
    if (!formData.code || formData.code.length < 6) {
      form.setError("code", { message: locales.errors.invalidCode });
      return;
    }

    const payload = formData.rememberDevice 
      ? { code: formData.code, rememberDevice: true } 
      : { code: formData.code };

    await handleContinue(payload);
  };

  const {
    formState: { isSubmitting },
    watch,
  } = form;

  // Validation for enabling submit button (e.g., code must be 6 digits)
  const isValidCode = (value: string) =>
    /^\d{6}$/.test(value);
  const otp = watch("code") ?? "";
  const isCodeValid = isValidCode(otp);

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit)}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            interactionTypeRef.current = "Enter";
          }
        }}
        className="mt-4"
      >
        {/* General error messages */}
        {hasError && generalErrors.length > 0 && (
          <div className="space-y-3 mb-4">
            {generalErrors.map((error: ErrorItem) => {
              let displayMessage = error.message;
              if (error.code === "invalid_otp") {
                displayMessage = locales.errors.invalidCode;
              }
              return (
                <ULThemeAlert
                  key={error.id}
                  variant="destructive"
                  onDismiss={() => dismiss(error.id)}
                >
                  <ULThemeAlertTitle>
                    {displayMessage || locales.errors.errorOccurred}
                  </ULThemeAlertTitle>
                </ULThemeAlert>
              );
            })}
          </div>
        )}

        {/* Code Input */}
        <FormField
          control={form.control}
          name="code"
          render={({ field }) => {
            // Check for SDK errors OR form errors
            const hasCodeError = codeErrors.length > 0 || !!form.formState.errors.code;
            
            return (
                <ULThemeStaticLabelField
                  {...field}
                  id="code"
                  label={codeLabel}
                  placeholder={texts?.codePlaceholder || locales.form.codePlaceholder}
                  type="text"
                  autoComplete="one-time-code"
                  inputMode="numeric"
                  pattern="\d{6}"
                  maxLength={6}
                  error={hasCodeError}
                />
            );
          }}
        />

        {/* Remember device checkbox */}
        {showRememberDevice && (
          <FormField
            control={form.control}
            name="rememberDevice"
            render={({ field }) => (
              <FormItem>
                <div className="flex items-center space-x-1 my-4 gap-1">
                  <ULThemeCheckbox
                    id="rememberDevice"
                    aria-labelledby="rememberDevice-label"
                    checked={field.value}
                    onCheckedChange={field.onChange}
                    className="w-5 h-5 border-input-border border-radius-[1]"
                  />
                  <label
                    id="rememberDevice-label"
                    htmlFor="rememberDevice"
                    className="text-(length:--ul-theme-font-body-text-size) cursor-pointer"
                  >
                    {rememberDeviceText}
                  </label>
                </div>
              </FormItem>
            )}
          />
        )}

        <div className="text-center">
          {/* Región viva de ARIA oculta visualmente para anunciar cuando el botón se habilita */}
          <div aria-live="polite" className="sr-only">
            {!isSubmitting && isCodeValid ? "El botón continuar se ha habilitado." : "El botón continuar se ha deshabilitado."}
          </div>

          {/* Continue button */}
          <ULThemeButton
            type="submit"
            className="w-full mt-6"
            variant="primary"
            aria-disabled={isSubmitting || !isCodeValid}
            onClick={(e) => {
              if (isSubmitting || !isCodeValid) {
                e.preventDefault();
                return;
              }
              if (e.nativeEvent.detail > 0) {
                interactionTypeRef.current = "Continuar";
              }
            }}
          >
            {continueText}
          </ULThemeButton>
        </div>
      </form>
      
      {/* Try another method link */}
      {shouldShowTryAnotherMethod && (
        <ULThemeButton
          type="button"
          onClick={() => {
            const canal = getCanalByClientId();
            pushClicHipervinculo(
              "Intentar con otro metodo otp",
              "/protege-tu-cuenta/auth0-guardian",
              canal
            );
            handleTryAnotherMethod();
          }}
          variant="link"
          size="link"
          className="mt-6 text-center"
        >
          {tryAnotherMethodText}
        </ULThemeButton>
      )}
    </Form>
  );
}

export default MfaOtpChallengeForm;
