import React, { useRef } from 'react';
import { ULThemeButton } from '../../../components/ULThemeButton';
import ULThemeLink from '../../../components/ULThemeLink';
import ULThemeSeparator from '../../../components/ULThemeSeparator';
import ULThemeTitle from '../../../components/ULThemeTitle';
import ULThemeSubtitle from '../../../components/ULThemeSubtitle';
import { ULThemeStaticLabelField } from '../../../components/form/ULThemeStaticLabelField';
import { Form, FormField, FormItem } from '../../../components/ui/form';
import { useForm } from 'react-hook-form';
import { useMfaOtpEnrollmentCodeManager } from '../hooks/useMfaOtpEnrollmentCodeManager';
import { getCanalByClientId } from '@/utils/helpers/canalUtils';
import { pushMfaOtpCodeContinuar, pushMfaOtpCodeIntentarOtroMetodo, pushMfaOtpCodeEscanearQR } from '@/utils/helpers/dataLayerUtils';

export const MfaOtpEnrollmentCodeForm: React.FC = () => {
  const {
    locales,
    secret,
    code,
    error,
    handleCodeChange,
    handleContinue,
    handlePickAuthenticator,
    handleScanQrCodeInstead,
    handleCopyCode,
  } = useMfaOtpEnrollmentCodeManager();

  const form = useForm({
    defaultValues: {
      code: code || '',
    },
  });

  const isEnterRef = useRef(false);

  return (
    <div className="flex flex-col items-center w-full max-w-md mx-auto">
      <div className="text-center mb-2">
        <ULThemeTitle className="text-center">{locales.title}</ULThemeTitle>
        <ULThemeSubtitle className="whitespace-pre-line">
          {locales.description.replace(' 2-', '\n2-')}
        </ULThemeSubtitle>
      </div>

      {secret && (
        <div className="w-full mb-4">
          <div className="bg-[#BDBDBD] text-[#717171] font-mono text-left py-3 px-4 rounded-md mb-4 tracking-widest opacity-50">
            {secret}
          </div>
          
          <div className="w-full text-center mb-4">
            <ULThemeLink
              href="#"
              onClick={(e: React.MouseEvent) => {
                e.preventDefault();
                const canal = getCanalByClientId() || 'Coppel.com';
                pushMfaOtpCodeEscanearQR('/protege-tu-cuenta/google-autenticator-codigo', canal);
                handleScanQrCodeInstead();
              }}
              className="text-sm font-bold text-[#0055FF]"
              aria-label={locales.scanQrCodeInstead}
              role="button"
            >
              {locales.scanQrCodeInstead}
            </ULThemeLink>
          </div>

          <ULThemeButton
            onClick={handleCopyCode}
            variant="outline"
            size="default"
            className="w-full !h-12 !rounded-[24px] !bg-white hover:!bg-[#1C42E8]/5 !text-[#1C42E8] !font-bold !text-[16px] !leading-[150%] !border !border-[#1C42E8] !shadow-none before:!hidden"
          >
            {locales.copyCodeButtonText}
          </ULThemeButton>
        </div>
      )}

      <ULThemeSeparator 
        text={locales.separatorText} 
        className="w-full [&_span]:!text-[#4A4A4A] [&_span]:!font-semibold my-2" 
      />

      <div className="w-full space-y-4 mt-2">
        <Form {...form}>
          <form 
            onSubmit={(e) => {
              e.preventDefault();
              const canal = getCanalByClientId() || 'Coppel.com';
              const interaction = isEnterRef.current ? 'Enter' : 'Continuar';
              pushMfaOtpCodeContinuar(interaction, '/protege-tu-cuenta/google-autenticator-codigo', canal);
              handleContinue();
              isEnterRef.current = false; // Reset
            }}
            className="w-full space-y-4"
          >
            <FormField
              control={form.control}
              name="code"
              render={({ field }) => (
                <FormItem>
                  <div className={error ? "[&_label]:!text-[#002D74] [&_input]:!text-[#002D74]" : ""}>
                    <ULThemeStaticLabelField
                      {...field}
                      label={locales.placeholder}
                      value={code}
                      onChange={(e) => {
                        field.onChange(e);
                        handleCodeChange(e);
                      }}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          isEnterRef.current = true;
                        }
                      }}
                      placeholder={locales.placeholder}
                      error={!!error}
                      maxLength={6}
                    />
                  </div>
                  {error && (
                    <div className="text-[#D32F2F] text-sm mt-1 text-left">
                      {error}
                    </div>
                  )}
                </FormItem>
              )}
            />

            <ULThemeButton
              type="submit"
              className="w-full bg-[#0055FF] hover:bg-[#0044CC] text-white font-bold py-2 px-4 rounded-full"
            >
              {locales.buttonText}
            </ULThemeButton>
          </form>
        </Form>

        <div className="text-center mt-4">
          <ULThemeLink
            href="#"
            onClick={(e: React.MouseEvent) => {
              e.preventDefault();
              const canal = getCanalByClientId() || 'Coppel.com';
              pushMfaOtpCodeIntentarOtroMetodo('/protege-tu-cuenta/google-autenticator-codigo', canal);
              handlePickAuthenticator();
            }}
            className="text-sm font-semibold text-[#1C42E8]"
            aria-label={locales.pickAuthenticatorText}
            role="button"
          >
            {locales.pickAuthenticatorText}
          </ULThemeLink>
        </div>
      </div>
    </div>
  );
};
