import { useEffect, useRef, useState } from "react";
import { useForm } from "react-hook-form";

import type { ContinueOptions, ErrorItem } from "@auth0/auth0-acul-react/types";
import { ChevronRight } from "lucide-react";

import {
  ULThemeFormMessage,
  ULThemeStaticLabelField,
} from "@/components/form";
import { Form, FormField, FormItem } from "@/components/ui/form";
import { Label } from "@/components/ui/label";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeCheckbox } from "@/components/ULThemeCheckbox";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import ULThemeSocialProviderButton from "@/components/ULThemeSocialProviderButton";

import { useMfaEmailChallengeManager } from "../hooks/useMFAEmailChallengeManager";
import { getAccessibleEmailText } from "@/utils/helpers/identifierUtils";
import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushErrorGeneral, pushMfaEmailContinuar } from "@/utils/helpers/dataLayerUtils";

function MfaEmailChallengeForm() {
  const {
    handleContinue,
    data,
    useErrors,
    texts,
    locales,
    enrolledEmails,
    handlePickEmail,
  } = useMfaEmailChallengeManager();
  const { errors, hasError, dismiss } = useErrors;
  const [isDisabled, setIsDisabled] = useState(true);

  useEffect(() => {
    if (Array.isArray(enrolledEmails) && enrolledEmails.length > 1) {
      setIsDisabled(false);
    } else {
      setIsDisabled(true);
    }
  }, [enrolledEmails]);

  // Initialize the form using react-hook-form
  const form = useForm<ContinueOptions>({
    defaultValues: {
      code: "",
      rememberDevice: false,
    },
  });

  const {
    formState: { isSubmitting },
    watch,
  } = form;

  const buttonText = texts?.buttonText || locales.form.buttonText;
  const codeLabelText =
    texts?.codeLabelText || locales.form.fields.code.codeLabelText;
  const rememberDeviceText =
    texts?.rememberDeviceText || locales.form.rememberDeviceText;

  // Extract general errors (not field-specific) from the SDK
  const generalErrors: ErrorItem[] =
    errors.byType("auth0")?.filter((error) => {
      return !error.field || error.field === null;
    }) || [];

  const codeSDKError = errors.byField("code")[0]?.message;
  const userEmail = data?.email || "";
  const accessibleEmailText = "Se envió el código al " + getAccessibleEmailText(userEmail);

  // Validation for enabling submit button (e.g., code must be 6 digits)
  const isValidCode = (value: string) =>
    /^\d{6}$/.test(value);
  const otp = watch("code") ?? "";
  const isCodeValid = isValidCode(otp);

  // Título y path para eventos de error
  const PAGE_ERROR_PATH = "/protege-tu-cuenta/correo";

  // Rastrear errores ya taggeados para no duplicar eventos
  const taggedErrorIds = useRef<Set<string>>(new Set());

  // dataLayer: disparar mensajeErrorGeneral cuando aparecen errores nuevos
  useEffect(() => {
    if (!hasError || generalErrors.length === 0) return;
    generalErrors.forEach((error) => {
      if (!taggedErrorIds.current.has(error.id)) {
        taggedErrorIds.current.add(error.id);
        pushErrorGeneral(
          PAGE_ERROR_PATH,
          error.id,
          error.message,
          getCanalByClientId()
        );
      }
    });
  }, [generalErrors, hasError]);

  // Rastrear si el envío fue por Enter o por clic en Continuar
  const interactionTypeRef = useRef<"Continuar" | "Enter">("Continuar");

  // Manejar el submit (detectar si fue con Enter o Click)
  const onSubmit = async (formData: ContinueOptions) => {
    pushMfaEmailContinuar(interactionTypeRef.current, "/protege-tu-cuenta/correo", getCanalByClientId());

    await handleContinue(formData.code, formData.rememberDevice);
  };

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit)}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            interactionTypeRef.current = "Enter";
          }
        }}
        className="flex flex-col gap-6"
      >
        {/* General error messages */}
        {hasError && generalErrors.length > 0 && (
          <div className="space-y-3 mb-4">
            {generalErrors.map((error: ErrorItem) => (
              <ULThemeAlert
                key={error.id}
                variant="destructive"
                onDismiss={() => dismiss(error.id)}
              >
                <ULThemeAlertTitle>{error.message}</ULThemeAlertTitle>
              </ULThemeAlert>
            ))}
          </div>
        )}

        {/* User Email */}
        <span id="email-description" className="sr-only">
          {accessibleEmailText}
        </span>
        <ULThemeSocialProviderButton
          type="button"
          displayName={locales.form.fields.email.identifierLabelText}
          buttonText={userEmail}
          iconEnd={
            !isDisabled && (
              <ChevronRight className="w-4 h-4 theme-universal:text-input-labels" />
            )
          }
          onClick={handlePickEmail}
          className="theme-universal:border-input-border rounded-2xl theme-universal:rounded-input !justify-start !pl-4 bg-[var(--coppel-color-button-disabled-bg)] [&>span]:!text-left [&>span]:!text-[var(--coppel-color-text-disabled)]"
          variant="ghost"
          iconComponent={undefined}
          disabled={isDisabled}
        ></ULThemeSocialProviderButton>

        {/* Code input field */}
        <FormField
          control={form.control}
          name="code"
          rules={{
            required: locales.form.fields.code.requiredText,
          }}
          render={({ field, fieldState }) => (
            <FormItem>
              <ULThemeStaticLabelField
                {...field}
                label={codeLabelText}
                type="text"
                inputMode="numeric"
                placeholder={locales.form.fields.code.placeholderText}
                autoFocus
                error={!!fieldState.error || !!codeSDKError}
                isRequired={true}
                aria-describedby="email-description"
                pattern="\d{6}"
                maxLength={6}
              />
              <ULThemeFormMessage
                sdkError={codeSDKError}
                hasFormError={!!fieldState.error}
              />
            </FormItem>
          )}
        />

        {/* Remember device checkbox */}
        {data?.showRememberDevice && (
          <FormField
            control={form.control}
            name="rememberDevice"
            render={({ field }) => (
              <FormItem>
                <div className="flex items-center gap-1">
                  <ULThemeCheckbox
                    id="rememberDevice"
                    checked={field.value}
                    onCheckedChange={field.onChange}
                    aria-labelledby="rememberDevice-label"
                    className="w-5 h-5 border-input-border"
                  />
                  <Label
                    id="rememberDevice-label"
                    htmlFor="rememberDevice"
                    className="text-(length:--ul-theme-font-body-text-size) cursor-pointer"
                  >
                    {rememberDeviceText}
                  </Label>
                </div>
              </FormItem>
            )}
          />
        )}

        {/* Submit button */}
        <ULThemeButton
          type="submit"
          variant="primary"
          className="w-full"
          aria-disabled={isSubmitting || !isCodeValid}
          onClick={(e) => {
            if (isSubmitting || !isCodeValid) {
              e.preventDefault();
              return;
            }
            if (e.nativeEvent.detail > 0) {
              interactionTypeRef.current = "Continuar";
            }
          }}
        >
          {isSubmitting ? `${locales.form.verificationText}...` : buttonText}
        </ULThemeButton>
      </form>
    </Form>
  );
}

export default MfaEmailChallengeForm;
