import React, { useEffect } from 'react';
import CoppelPageLayout from '../../components/CoppelPageLayout';
import ULThemeCard from '../../components/ULThemeCard';
import { MfaOtpEnrollmentQRForm } from './components/MfaOtpEnrollmentQRForm';
import locales from '@/screens/mfa-otp-enrollment-qr/locales/es.json';
import { getCanalByClientId } from '@/utils/helpers/canalUtils';
import { pushMfaOtpPageView } from '@/utils/helpers/dataLayerUtils';

const MfaOtpEnrollmentQRScreen: React.FC = () => {
  document.title = locales.pageTitle || "";

  useEffect(() => {
    const canal = getCanalByClientId() || 'Coppel.com';
    pushMfaOtpPageView('/protege-tu-cuenta/google-autenticator', 'Protege tu cuenta - Autenticator', canal);
  }, []);

  return (
    <CoppelPageLayout className="theme-universal">
      <ULThemeCard className="w-full max-w-[400px] gap-0">
        <MfaOtpEnrollmentQRForm />
      </ULThemeCard>
    </CoppelPageLayout>
  );
};

export default MfaOtpEnrollmentQRScreen;
