import { useForm } from "react-hook-form";

import type {
  ErrorItem,
  ResetPasswordRequestOptions,
} from "@auth0/auth0-acul-react/types";

import Captcha from "@/components/Captcha/index";
import { ULThemeFormMessage, ULThemeStaticLabelField } from "@/components/form";
import { Form, FormField, FormItem } from "@/components/ui/form";
import { ULThemeButton } from "@/components/ULThemeButton";
import { ULThemeAlert, ULThemeAlertTitle } from "@/components/ULThemeError";
import { useCaptcha } from "@/hooks/useCaptcha";
import { getIdentifierDetails } from "@/utils/helpers/identifierUtils";

import { getCanalByClientId } from "@/utils/helpers/canalUtils";
import { pushResetPasswordRequestContinuar } from "@/utils/helpers/dataLayerUtils";

import { useResetPasswordRequestManager } from "../hooks/resetPasswordRequestManager";
function ResetPasswordRequestForm() {
  const {
    handleResetPasswordRequest,
    texts,
    isCaptchaAvailable,
    captcha,
    activeIdentifiers,
    useErrors,
    locales,
    inputfield
  } = useResetPasswordRequestManager();
  const { errors, hasError, dismiss } = useErrors;

  // Initialize the form using react-hook-form
  const form = useForm<ResetPasswordRequestOptions>({
    defaultValues: {
      username: String(inputfield),
      captcha: "",
    },
  });

  const {
    formState: { isSubmitting },
    watch,
  } = form;

  const usernameValue = watch("username");
  const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(usernameValue ?? "");

  const buttonText = texts?.buttonText || locales.form.button;
  const captchaLabel = texts?.captchaCodePlaceholder
    ? `${texts.captchaCodePlaceholder}*`
    : `${locales.form.fields.captcha.label}*`;
  const identifierDetails = getIdentifierDetails(
    activeIdentifiers,
    texts,
    false
  );

  // Extract general errors (not field-specific) from the SDK
  const generalErrors: ErrorItem[] =
    errors.byType("auth0")?.filter((error) => {
      return !error.field || error.field === null;
    }) || [];

  const usernameSDKError = errors.byField("username")[0]?.message;
  const captchaSDKError = errors.byField("captcha")[0]?.message;

  const { captchaConfig, captchaProps, captchaValue } = useCaptcha(
    captcha || undefined,
    captchaLabel
  );

  const onSubmit = async (formData: ResetPasswordRequestOptions) => {
    const canal = getCanalByClientId();
    const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.username);
    const cuentaTipo = isEmail ? "Correo" : "Celular";
    
    pushResetPasswordRequestContinuar(
      "Continuar",
      "/recuperacion-contrasena",
      cuentaTipo,
      canal
    );
    await handleResetPasswordRequest(formData.username, captchaValue);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLFormElement>) => {
    if (e.key === "Enter") {
      const username = form.getValues("username");
      const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(username);
      const cuentaTipo = isEmail ? "Correo" : "Celular";
      const canal = getCanalByClientId();
      
      pushResetPasswordRequestContinuar(
        "Enter",
        "/recuperacion-contrasena",
        cuentaTipo,
        canal
      );
    }
  };

  return (
    <Form {...form}>
      <div role="group" aria-label="Recuperar contraseña">
        <form onSubmit={form.handleSubmit(onSubmit)} onKeyDown={handleKeyDown}>
          {/* General error messages */}
          {hasError && generalErrors.length > 0 && (
            <div className="space-y-3 mb-4" aria-live="polite" aria-atomic="true">
            {generalErrors.map((error) => (
              <ULThemeAlert
                key={error.id}
                variant="destructive"
                onDismiss={() => dismiss(error.id)}
              >
                <ULThemeAlertTitle>{error.message}</ULThemeAlertTitle>
              </ULThemeAlert>
            ))}
          </div>
        )}

        {/* Username or Email or Phone pre-filled input field */}
        <FormField
          control={form.control}
          name="username"
          render={({ field, fieldState }) => (
            <FormItem>
              <ULThemeStaticLabelField
                {...field}
                label={
                  locales.form.fields.username.label || identifierDetails.label
                }
                placeholder={
                  locales.form.fields.username.placeholder ||
                  "Escribe tu correo"
                }
                type={identifierDetails.type}
                inputMode="text"
                autoComplete={identifierDetails.autoComplete}
                autoFocus
                error={!!fieldState.error || !!usernameSDKError}
                aria-invalid={!!fieldState.error || !!usernameSDKError}
                aria-describedby="username-error"
              />
              <div id="username-error">
                <ULThemeFormMessage
                  sdkError={usernameSDKError}
                  hasFormError={!!fieldState.error}
                />
              </div>
            </FormItem>
          )}
        />

        {/* CAPTCHA Box */}
        {isCaptchaAvailable && captchaConfig && (
          <Captcha
            control={form.control}
            name="captcha"
            captcha={captchaConfig}
            {...captchaProps}
            sdkError={captchaSDKError}
            rules={{
              required: locales.form.fields.captcha.required,
            }}
            className="mt-2 mb-4"
          />
        )}

        {/* Submit button */}
          <ULThemeButton
            type="submit"
            variant="primary"
            className="w-full mt-6"
            disabled={isSubmitting || !isValidEmail}
          >
            {isSubmitting ? `${locales.form.submittingState}...` : buttonText}
          </ULThemeButton>
        </form>
      </div>
    </Form>
  );
}

export default ResetPasswordRequestForm;
