import React, { useEffect } from 'react';
import CoppelPageLayout from '../../components/CoppelPageLayout';
import ULThemeCard from '../../components/ULThemeCard';
import { MfaOtpEnrollmentCodeForm } from './components/MfaOtpEnrollmentCodeForm';
import locales from '@/screens/mfa-otp-enrollment-code/locales/es.json';
import { getCanalByClientId } from '@/utils/helpers/canalUtils';
import { pushMfaOtpCodePageView } from '@/utils/helpers/dataLayerUtils';

const MfaOtpEnrollmentCodeScreen: React.FC = () => {
  document.title = locales.pageTitle || "";

  useEffect(() => {
    const canal = getCanalByClientId() || 'Coppel.com';
    pushMfaOtpCodePageView('/protege-tu-cuenta/google-autenticator-codigo', 'Protege tu cuenta - Codigo', canal);
  }, []);

  return (
    <CoppelPageLayout className="theme-universal">
      <ULThemeCard className="w-full max-w-[400px] gap-0">
        <MfaOtpEnrollmentCodeForm />
      </ULThemeCard>
    </CoppelPageLayout>
  );
};

export default MfaOtpEnrollmentCodeScreen;